function installGitHubOffline(app2, host, onActivity) {
  let modal = null;
  const button = document.getElementById("github-vault-offline");
  const open = () => {
    if (app2.changingVault) return;
    if (modal?.isOpen) {
      modal.modalEl.focus();
      return;
    }
    const source = host.offlineSource();
    if (!source) return;
    const current = modal = new Modal(app2);
    current.setTitle("Offline GitHub vault");
    current.containerEl.dataset.githubOfflineDialog = "";
    let controls = null;
    current.onOpen = () => {
      controls = new GitHubOfflineControls(current.contentEl, host.reader, source.mount, source.cacheOnly, onActivity);
    };
    current.onClose = () => {
      controls?.dispose();
      if (modal === current) modal = null;
    };
    current.open();
  };
  button?.addEventListener("click", open);
  host.onSourceChange(() => {
    modal?.close();
    if (button) button.hidden = !host.active;
  });
  app2.registerLeaveGuard(() => {
    modal?.close();
  });
  app2.commands.addCommand({ id: "github-vault:offline", name: "GitHub vault: Download for offline use", checkCallback: (checking) => {
    if (!host.active || app2.changingVault) return false;
    if (!checking) open();
    return true;
  } });
}

